targets.query:
import "date"
import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "light" and r._field == "on" and r._value == 0.0)
  |> map(fn: (r) => ({ r with _value: float(v: date.hour(t: r._time)) + float(v: date.minute(t: r._time)) / 60.0 }))
  // Keep only plausible lamp-off times. `light/state` is RETAINED, so every
  // Telegraf reconnect replays it and lands a phantom OFF at the restart time —
  // one such artifact sits at 22:44 on 2026-07-30. The real switch-off is always
  // in the evening window, so anything outside it is not a lamp event.
  |> filter(fn: (r) => r._value >= 17.0 and r._value <= 21.5)
  |> aggregateWindow(every: 1d, fn: last, createEmpty: false)
